CREATE OR REPLACE FUNCTION public.create_friend_request(p_friend_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_me uuid := auth.uid(); v_nick text; v_exist int; v_new_id uuid;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok',false,'error','noauth'); END IF;
  IF v_me = p_friend_id THEN RETURN jsonb_build_object('ok',false,'error','self'); END IF;
  SELECT count(*) INTO v_exist FROM public.friends
    WHERE (user_id=v_me AND friend_id=p_friend_id) OR (user_id=p_friend_id AND friend_id=v_me);
  IF v_exist > 0 THEN RETURN jsonb_build_object('ok',false,'error','exists'); END IF;
  INSERT INTO public.friends (user_id, friend_id, status) VALUES (v_me, p_friend_id, 'pending') RETURNING id INTO v_new_id;
  SELECT nickname INTO v_nick FROM public.profiles WHERE id = v_me;
  INSERT INTO public.notifications (user_id, type, title, body, link, is_read)
    VALUES (p_friend_id, 'friend_request', COALESCE(v_nick,'有人') || ' 想加你为好友', '点击同意或拒绝', '/friends/request?id=' || v_new_id::text, false);
  RETURN jsonb_build_object('ok',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_user(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
BEGIN
  DELETE FROM auth.users WHERE id = p_user_id;
  RETURN jsonb_build_object('ok', true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.find_or_create_dm(p_friend_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_me       uuid := auth.uid();
  v_existing uuid;
  v_chan_id  uuid;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('error', 'not authenticated');
  END IF;
  IF p_friend_id IS NULL OR p_friend_id = v_me THEN
    RETURN jsonb_build_object('error', 'invalid friend');
  END IF;

  -- 必须双方已为好友关系（accepted），陌生人无法打开 DM
  IF NOT EXISTS (
    SELECT 1 FROM public.friends f
    WHERE ((f.user_id = v_me AND f.friend_id = p_friend_id)
        OR (f.user_id = p_friend_id AND f.friend_id = v_me))
      AND f.status = 'accepted'
  ) THEN
    RETURN jsonb_build_object('error', 'only friends can chat');
  END IF;

  -- 已存在两人私有房间则直接返回
  SELECT c.id INTO v_existing
  FROM channels c
  WHERE c.type = 'dm'
    AND EXISTS (SELECT 1 FROM channel_members cm1 WHERE cm1.channel_id = c.id AND cm1.user_id = v_me)
    AND EXISTS (SELECT 1 FROM channel_members cm2 WHERE cm2.channel_id = c.id AND cm2.user_id = p_friend_id)
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('id', v_existing, 'existing', true);
  END IF;

  -- name 用内部唯一标识避免 UNIQUE 冲突；type='dm' 使前端可过滤不进公共频道列表
  INSERT INTO channels (name, description, type, created_by)
  VALUES ('dm:' || v_me::text || ':' || p_friend_id::text, 'private chat', 'dm', v_me)
  RETURNING id INTO v_chan_id;

  INSERT INTO channel_members (channel_id, user_id) VALUES (v_chan_id, v_me);
  INSERT INTO channel_members (channel_id, user_id) VALUES (v_chan_id, p_friend_id);

  RETURN jsonb_build_object('id', v_chan_id, 'existing', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_mentions(p_message_id uuid, p_author_id uuid, p_channel_id uuid, p_content text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_author text; v_channel text; v_name text; v_target uuid;
BEGIN
  SELECT nickname INTO v_author FROM public.profiles WHERE id = p_author_id;
  SELECT name INTO v_channel FROM public.channels WHERE id = p_channel_id;
  FOR v_name IN
    SELECT DISTINCT m[1] FROM regexp_matches(p_content, '@([^[:space:]@]+)', 'g') m
  LOOP
    SELECT id INTO v_target FROM public.profiles WHERE username = v_name OR nickname = v_name LIMIT 1;
    IF v_target IS NOT NULL AND v_target <> p_author_id THEN
      INSERT INTO public.notifications (user_id, type, title, body, link, is_read)
      VALUES (
        v_target, 'mention',
        COALESCE(v_author,'有人') || ' 在 #' || COALESCE(v_channel,'频道') || ' 提到了你',
        CASE WHEN length(p_content) > 60 THEN left(p_content,60) || '…' ELSE p_content END,
        '/channel/' || p_channel_id::text || '#msg-' || p_message_id::text,
        false
      );
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.overturn_moderation(p_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_author  UUID;
  v_channel TEXT;
  v_count   INT;
BEGIN
  -- 取消息作者与频道名
  SELECT m.author_id,
         (SELECT c.name FROM channels c WHERE c.id = m.channel_id)
    INTO v_author, v_channel
  FROM messages m
  WHERE m.id = p_message_id;

  IF v_author IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'message_not_found');
  END IF;

  -- 1) 清待审标记 + 标记已撤销
  UPDATE messages
     SET reviewed = TRUE,
         mod_overturned = TRUE
   WHERE id = p_message_id;

  -- 2) 删除机器人警告评论（is_mod=true 的子消息）
  DELETE FROM messages WHERE parent_id = p_message_id AND is_mod = TRUE;

  -- 3) 扣回警告计数（不低于 0）
  UPDATE profiles
     SET warning_count = GREATEST(0, COALESCE(warning_count, 0) - 1)
   WHERE id = v_author;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- 4) 给用户发「误判已撤销」通知
  INSERT INTO notifications (user_id, type, title, body, is_read)
  VALUES (
    v_author,
    'system',
    '审核误判已撤销',
    '您在 #' || COALESCE(v_channel, '频道') || ' 的一条消息被 AI 误标为待审，管理员已确认内容正常并撤销标记。给您带来不便，敬请谅解！',
    FALSE
  );

  RETURN jsonb_build_object('ok', true, 'warning_rolled_back', v_count > 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.publish_message_realtime()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  raw_mention text; mention text; mentioned_id uuid; author_name text;
BEGIN
  PERFORM realtime.publish('chat:' || NEW.channel_id::text, 'new_message', jsonb_build_object(
    'id', NEW.id, 'channel_id', NEW.channel_id, 'author_id', NEW.author_id,
    'content', NEW.content, 'content_type', NEW.content_type, 'is_pinned', NEW.is_pinned,
    'parent_id', NEW.parent_id, 'created_at', NEW.created_at));
  IF NEW.content_type = 'text' THEN
    SELECT nickname INTO author_name FROM public.profiles WHERE id = NEW.author_id;
    FOR raw_mention IN SELECT DISTINCT (regexp_matches(NEW.content, '@(\S+)', 'g'))[1] LOOP
      mention := regexp_replace(raw_mention, '[^a-zA-Z0-9_]+$', '');
      IF mention <> '' THEN
        SELECT id INTO mentioned_id FROM public.profiles WHERE username = mention;
        IF mentioned_id IS NOT NULL AND mentioned_id <> NEW.author_id THEN
          INSERT INTO public.notifications (user_id, type, title, body, link)
          VALUES (mentioned_id, 'mention', COALESCE(author_name, '有人') || ' 在频道中@了你', NEW.content, 'channel/' || NEW.channel_id::text);
        END IF;
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_friend(p_friend_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_me uuid := auth.uid();
BEGIN
  DELETE FROM public.friends
    WHERE (user_id=v_me AND friend_id=p_friend_id) OR (user_id=p_friend_id AND friend_id=v_me);
  RETURN jsonb_build_object('ok',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.search_users_safe(p_keyword text, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_kw text;
  v_base text;
BEGIN
  v_kw := COALESCE(p_keyword, '') || '';
  IF length(v_kw) = 0 OR length(v_kw) > 30 THEN
    RETURN '[]'::jsonb;
  END IF;
  -- LIKE 元字符转义
  v_base := replace(replace(replace(v_kw, '\', '\\'), '%', '\%'), '_', '\_');
  RETURN (
    SELECT COALESCE(
      jsonb_agg(jsonb_build_object(
        'id', p.id,
        'username', p.username,
        'nickname', p.nickname,
        'avatar_url', p.avatar_url
      )), '[]'::jsonb
    )
    FROM profiles p
    WHERE p.username ILIKE '%' || v_base || '%' ESCAPE '\'
       OR p.nickname ILIKE '%' || v_base || '%' ESCAPE '\'
    LIMIT LEAST(COALESCE(p_limit, 5), 20)
  );
END;
$function$
